package com.docgen.service

import java.io.ByteArrayOutputStream
import java.nio.charset.Charset
import java.security.MessageDigest
import java.util.Base64
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

data class ServiceToken(val issuer: String, val subject: String, val timestamp: Long, val signature: String)

class CrossServiceAuthenticator(private val sharedSecret: String) {

    private val HMAC_ALGORITHM = "HmacSHA256"
    private val TOKEN_VALIDITY_MS = 300_000L // 5 minutes

    fun validateToken(token: ServiceToken): Boolean {
        val now = System.currentTimeMillis()
        if (now - token.timestamp > TOKEN_VALIDITY_MS) return false
        val expectedSig = computeSignature(token.issuer, token.subject, token.timestamp)
        return constantTimeEquals(expectedSig, token.signature)
    }

    fun computeSignature(issuer: String, subject: String, timestamp: Long): String {
        val payload = "$issuer|$subject|$timestamp"
        val mac = Mac.getInstance(HMAC_ALGORITHM)
        mac.init(SecretKeySpec(sharedSecret.toByteArray(Charsets.UTF_8), HMAC_ALGORITHM))
        return Base64.getEncoder().encodeToString(mac.doFinal(payload.toByteArray(Charsets.UTF_8)))
    }

    private fun constantTimeEquals(a: String, b: String): Boolean {
        if (a.length != b.length) return false
        var result = 0
        for (i in a.indices) {
            result = result or (a[i].code xor b[i].code)
        }
        return result == 0
    }
}

class PdfContentEncoder(private val charset: Charset = Charsets.UTF_8) {

    companion object {
        private val PDF_ESCAPE_MAP = mapOf(
            '(' to "\\(",
            ')' to "\\)",
            '\\' to "\\\\"
        )
        // PDFDocEncoding maps 0x80-0x9F to specific Unicode codepoints
        private val PDFDOC_ENCODING_OVERRIDES = mapOf(
            0x80 to 0x2022, // bullet
            0x81 to 0x2020, // dagger
            0x82 to 0x2021, // double dagger
            0x83 to 0x2026, // ellipsis
            0x84 to 0x2014, // em dash
            0x85 to 0x2013, // en dash
            0x86 to 0x0192, // florin
            0x87 to 0x2044, // fraction slash
            0x88 to 0x2039, // left single guillemet
            0x89 to 0x203A, // right single guillemet
            0x8A to 0x2212, // minus
            0x8B to 0x2030, // per mille
            0x8C to 0x201E, // double low-9 quotation
            0x8D to 0x201C, // left double quotation
            0x8E to 0x201D, // right double quotation
            0x8F to 0x2018, // left single quotation
            0x90 to 0x2019, // right single quotation
            0x91 to 0x201A, // single low-9 quotation
            0x92 to 0x2122, // trademark
            0x93 to 0xFB01, // fi ligature
            0x94 to 0xFB02, // fl ligature
            0x95 to 0x0141, // L with stroke
            0x96 to 0x0152, // OE ligature
            0x97 to 0x0160, // S with caron
            0x98 to 0x0178, // Y with diaeresis
            0x99 to 0x017D, // Z with caron
            0x9A to 0x0131, // dotless i
            0x9B to 0x0142  // l with stroke
        )
    }

    fun encodeToPdfString(input: String): String {
        val normalized = normalizeForPdfDoc(input)
        return escapePdfLiteral(normalized)
    }

    private fun normalizeForPdfDoc(input: String): String {
        val sb = StringBuilder()
        for (ch in input) {
            val codePoint = ch.code
            // Check if this Unicode char maps to a PDFDocEncoding byte
            val pdfDocByte = PDFDOC_ENCODING_OVERRIDES.entries
                .firstOrNull { it.value == codePoint }?.key
            if (pdfDocByte != null) {
                sb.append(pdfDocByte.toChar())
            } else if (codePoint < 0x100) {
                sb.append(ch)
            } else {
                // Encode as UTF-16BE with BOM for non-PDFDoc chars
                sb.append(ch)
            }
        }
        return sb.toString()
    }

    fun escapePdfLiteral(input: String): String {
        val sb = StringBuilder("(")
        for (ch in input) {
            val escaped = PDF_ESCAPE_MAP[ch]
            if (escaped != null) {
                sb.append(escaped)
            } else if (ch.code < 0x20 || ch.code > 0x7E) {
                // Octal escape for non-printable/non-ASCII
                sb.append(String.format("\\%03o", ch.code and 0xFF))
            } else {
                sb.append(ch)
            }
        }
        sb.append(")")
        return sb.toString()
    }
}

class PdfGenerationService(
    private val authenticator: CrossServiceAuthenticator,
    private val encoder: PdfContentEncoder = PdfContentEncoder()
) {

    fun generateInvoicePdf(token: ServiceToken, invoiceData: Map<String, String>): ByteArray {
        if (!authenticator.validateToken(token)) {
            throw SecurityException("Invalid service token")
        }
        return buildPdf(invoiceData)
    }

    private fun buildPdf(data: Map<String, String>): ByteArray {
        val output = ByteArrayOutputStream()
        output.write("%PDF-1.4\n".toByteArray())

        val objects = mutableListOf<String>()

        // Catalog
        objects.add("1 0 obj\n<< /Type /Catalog /Pages 2 0 R >>\nendobj\n")
        // Pages
        objects.add("2 0 obj\n<< /Type /Pages /Kids [3 0 R] /Count 1 >>\nendobj\n")
        // Page
        objects.add("3 0 obj\n<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources << /Font << /F1 5 0 R >> >> >>\nendobj\n")

        // Content stream with user data
        val contentStream = buildContentStream(data)
        objects.add("4 0 obj\n<< /Length ${contentStream.length} >>\nstream\n${contentStream}\nendstream\nendobj\n")

        // Font
        objects.add("5 0 obj\n<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>\nendobj\n")

        for (obj in objects) {
            output.write(obj.toByteArray())
        }

        output.write("%%EOF\n".toByteArray())
        return output.toByteArray()
    }

    private fun buildContentStream(data: Map<String, String>): String {
        val sb = StringBuilder()
        sb.append("BT\n/F1 12 Tf\n")
        var yPos = 750

        for ((key, value) in data) {
            val encodedKey = encoder.encodeToPdfString(key)
            val encodedValue = encoder.encodeToPdfString(value)
            sb.append("1 0 0 1 50 $yPos Tm\n")
            sb.append("$encodedKey Tj\n")
            sb.append("1 0 0 1 200 $yPos Tm\n")
            sb.append("$encodedValue Tj\n")
            yPos -= 20
        }

        sb.append("ET\n")
        return sb.toString()
    }
}

class InvoiceController(sharedSecret: String) {
    private val authenticator = CrossServiceAuthenticator(sharedSecret)
    private val pdfService = PdfGenerationService(authenticator)

    fun handleRequest(headers: Map<String, String>, body: Map<String, String>): ByteArray {
        val tokenStr = headers["X-Service-Token"] ?: throw SecurityException("Missing token")
        val token = parseToken(tokenStr)
        return pdfService.generateInvoicePdf(token, body)
    }

    private fun parseToken(raw: String): ServiceToken {
        // Format: base64(issuer|subject|timestamp|signature)
        val decoded = String(Base64.getDecoder().decode(raw), Charsets.UTF_8)
        val parts = decoded.split("|")
        if (parts.size != 4) throw SecurityException("Malformed token")
        return ServiceToken(
            issuer = parts[0],
            subject = parts[1],
            timestamp = parts[2].toLongOrNull() ?: throw SecurityException("Invalid timestamp"),
            signature = parts[3]
        )
    }
}
